(window.webpackJsonp=window.webpackJsonp||[]).push([[40],{488:function(n,e,r){"use strict";r.r(e);var a=r(25),t=Object(a.a)({},(function(){var n=this._self._c;return n("ContentSlotsDistributor",{attrs:{"slot-key":this.$parent.slotKey}},[n("h1",{attrs:{id:"_3-clickpoints-点击绘点"}},[n("a",{staticClass:"header-anchor",attrs:{href:"#_3-clickpoints-点击绘点"}},[this._v("#")]),this._v(" 3/clickpoints 点击绘点")]),this._v(" "),n("div",{staticClass:"language- extra-class"},[n("pre",{pre:!0,attrs:{class:"language-text"}},[n("code",[this._v("/**\n * Create a program object and make current\n * @param gl GL context\n * @param vshader a vertex shader program (string)\n * @param fshader a fragment shader program (string)\n * @return true, if the program object was created and successfully made current \n */\nfunction initShaders(gl, vshader, fshader) {\n  var program = createProgram(gl, vshader, fshader);\n  if (!program) {\n    console.log('Failed to create program');\n    return false;\n  }\n\n  gl.useProgram(program);\n  gl.program = program;\n\n  return true;\n}\n\n/**\n * Create the linked program object\n * @param gl GL context\n * @param vshader a vertex shader program (string)\n * @param fshader a fragment shader program (string)\n * @return created program object, or null if the creation has failed\n */\nfunction createProgram(gl, vshader, fshader) {\n  // Create shader object\n  var vertexShader = loadShader(gl, gl.VERTEX_SHADER, vshader);\n  var fragmentShader = loadShader(gl, gl.FRAGMENT_SHADER, fshader);\n  if (!vertexShader || !fragmentShader) {\n    return null;\n  }\n\n  // Create a program object\n  var program = gl.createProgram();\n  if (!program) {\n    return null;\n  }\n\n  // Attach the shader objects\n  gl.attachShader(program, vertexShader);\n  gl.attachShader(program, fragmentShader);\n\n  // Link the program object\n  gl.linkProgram(program);\n\n  // Check the result of linking\n  var linked = gl.getProgramParameter(program, gl.LINK_STATUS);\n  if (!linked) {\n    var error = gl.getProgramInfoLog(program);\n    console.log('Failed to link program: ' + error);\n    gl.deleteProgram(program);\n    gl.deleteShader(fragmentShader);\n    gl.deleteShader(vertexShader);\n    return null;\n  }\n  return program;\n}\n\n/**\n * Create a shader object\n * @param gl GL context\n * @param type the type of the shader object to be created\n * @param source shader program (string)\n * @return created shader object, or null if the creation has failed.\n */\nfunction loadShader(gl, type, source) {\n  // Create shader object\n  var shader = gl.createShader(type);\n  if (shader == null) {\n    console.log('unable to create shader');\n    return null;\n  }\n\n  // Set the shader program\n  gl.shaderSource(shader, source);\n\n  // Compile the shader\n  gl.compileShader(shader);\n\n  // Check the result of compilation\n  var compiled = gl.getShaderParameter(shader, gl.COMPILE_STATUS);\n  if (!compiled) {\n    var error = gl.getShaderInfoLog(shader);\n    console.log('Failed to compile shader: ' + error);\n    gl.deleteShader(shader);\n    return null;\n  }\n\n  return shader;\n}\nfunction initWebGL(canvas) {\n  const dpr = window.devicePixelRatio || 1;\n  console.log(dpr);\n  canvas.width = 400 * dpr;\n  canvas.height = 300 * dpr;\n  canvas.style.width = '400px';\n  canvas.style.height = '300px'\n\n  const gl = canvas.getContext('webgl');\n  if (!gl) {\n    console.error('Failed to get WebGL context');\n    return null;\n  }\n  gl.viewport(0, 0, canvas.width, canvas.height);\n  gl.clearColor(0, 0, 0, 1);\n  return gl;\n}\nwindow.onload = function(){\n\n    /*\n        着色器是申明attribute变量\n        attribute变量赋值给gl_Position\n        向attribute变量传递变量\n     */\n    //顶点着色器程序\n    var VSHADER_SOURCE = \n    'attribute vec4 a_Position;\\n'+ \n    'void main(){\\n'+\n    ' gl_Position = a_Position;\\n'+\n    ' gl_PointSize = 10.0;\\n'+\n    '}\\n';\n\n    // //片元着色器\n    var FSHADER_SOURCE = \n    'void main(){\\n'+\n    ' gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0);\\n'+\n    '}\\n';\n \n\n    var canvas = document.getElementById('webgl')\n    var gl = initWebGL(canvas)\n    if(!gl){\n        console.log('Failed to get thd rendering context for webgl')\n        return;\n    }\n\n    //初始着色器\n    if(!initShaders(gl,VSHADER_SOURCE,FSHADER_SOURCE)){\n        console.log('failed to initialize shaders')\n        return;\n    }\n\n    //获取变量attribute的存储位置\n    var a_Position = gl.getAttribLocation(gl.program,'a_Position');\n    \n    if(a_Position < 0){\n        console.log('failed to get the storage location of a_Position')\n    }  \n\n\n   canvas.onmousedown = function(ev){click(ev,gl,canvas,a_Position);}\n\n    //将顶点位置传输给attribute变量\n    //gl.vertexAttrib3f(a_Position,0.0,0.0,0.0); \n\n\n    var g_points = [];  //鼠标点击位置数组\n    function click(ev,gl,canvas,a_Position){\n        var x = ev.clientX;\n        var y = ev.clientY;\n        var rect = ev.target.getBoundingClientRect();\n        x = ((x - rect.left) - canvas.width/2)/(canvas.width/2);\n        y = (canvas.height/2 - (y-rect.top))/(canvas.height/2);\n        console.log(x,y);\n        g_points.push([x,y]);\n\n        // //清空<canvas>\n        //gl.clear(gl.COLOR_BUFFER_BIT)\n        var len = g_points.length;\n        for(var i=0;i<len;i++){\n            //将点的位置传递到变量中\n            gl.vertexAttrib3f(a_Position,g_points[i][0],g_points[i][1],0.0)\n\n            //绘制点\n            gl.drawArrays(gl.POINTS,0,1)\n        }\n        \n    }\n\n    \n\n\n    //设置<canvas>背景色\n    // gl.clearColor(0.0,0.0,0.0,1.0);\n\n    // //清空<canvas>\n    // gl.clear(gl.COLOR_BUFFER_BIT)\n\n    // //绘制一个点\n    // gl.drawArrays(gl.POINTS,0,1)\n    \n\n}\n")])])])])}),[],!1,null,null,null);e.default=t.exports}}]);